INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40111, 'Genesis 20:7', 'Genesis', 20, 7, 'اوس هغه ښځه بېرته خپل مېړه ته ورکړه. هغه نبي دی او هغه به ستا دپاره دعا وکړي، ترڅو ژوندی پاتې شې. خو که چېرې هغه بېرته ورنه کړې، په دې پوه شه چې ته او ستا ټول خلک به مړه شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_7.mp3', '', 1761754199, 1761754199),
(40112, 'Genesis 20:8', 'Genesis', 20, 8, 'سبا سهار وختي ابي‌ملک خپل ټول درباریان راوغوښتل او څه چې پېښ شوي وو هغوی ته یې بیان کړل او هغوی ډېر ووېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_8.mp3', '', 1761754199, 1761754199),
(40113, 'Genesis 20:9', 'Genesis', 20, 9, 'بیا ابي‌ملک ابراهیم راوغوښت او پوښتنه یې ترې وکړه: «زمونږ سره دې څه وکړل؟ ما ستا سره څه بد کړي وو چې داسې لوی مصیبت دې په ما او زما په پاچاهۍ باندې راوست؟ تا زما سره داسې کار وکړ چې د کولو نه ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_9.mp3', '', 1761754199, 1761754199),
(40114, 'Genesis 20:10', 'Genesis', 20, 10, 'بیا ابي‌ملک د ابراهیم څخه پوښتنه وکړه: «داسې کار دې ولې وکړ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_10.mp3', '', 1761754199, 1761754199),
(40115, 'Genesis 20:11', 'Genesis', 20, 11, 'ابراهیم ځواب ورکړ: «ما فکر وکړ چې د دې ځای خلک د خدای څخه نه وېریږي او ما به د خپلې ښځې په خاطر ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_11.mp3', '', 1761754199, 1761754199),
(40116, 'Genesis 20:12', 'Genesis', 20, 12, 'هغه په رښتیا سره زما خور ده، هغه زما ناسکه خور ده. هغه زما د پلار لور ده، خو زما د مور لور نه ده او ما د هغې سره واده کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_12.mp3', '', 1761754199, 1761754199),
(40117, 'Genesis 20:13', 'Genesis', 20, 13, 'کله چې خدای زه د خپل پلار د کور څخه پردي هېواد ته ولېږلم، ما هغې ته وویل: ‹دا به زما سره ستا وفاداري وي چې مونږ هرځای ته لاړ شو، زما په هکله به وایې چې هغه زما ورور دی.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_13.mp3', '', 1761754199, 1761754199),
(40118, 'Genesis 20:14', 'Genesis', 20, 14, 'نو ابي‌ملک ابراهیم ته پسونه او غویان، غلامان او وینځې ورکړل او د هغه ښځه ساره یې بېرته هغه ته وسپارله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_14.mp3', '', 1761754199, 1761754199),
(40119, 'Genesis 20:15', 'Genesis', 20, 15, 'ابي‌ملک وویل: «زما ټوله ځمکه ستا په مخکې ده، هرځای چې ستا خوښ وي هلته واوسېږه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_15.mp3', '', 1761754199, 1761754199),
(40120, 'Genesis 20:16', 'Genesis', 20, 16, 'هغه ساره ته وویل: «زه ستا ورور ته د سپینو زرو زر سیکې ورکوم، ترڅو هغو ټولو خلکو ته چې ستا سره دي دا ثابته شي چې ته بې‌ګناه یې او هر یو په دې باندې پوه شي چې تا کومه غلطي نه ده کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_16.mp3', '', 1761754199, 1761754199),
(40121, 'Job 25:1', 'Job', 25, 1, 'بيا شوحى بِلداد جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_1.mp3', '', 1761754199, 1761754199),
(40122, 'Job 25:2', 'Job', 25, 2, '”اختيار او يره د خُدائ پاک سره دى، هغه په آسمانى بادشاهۍ کښې امن قائموى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_2.mp3', '', 1761754199, 1761754199),
(40123, 'Job 25:3', 'Job', 25, 3, 'د هغۀ آسمانى لښکر څوک شمارلے شى؟ د هغۀ رڼا په چا باندې نۀ ځليږى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_3.mp3', '', 1761754199, 1761754199),
(40124, 'Job 25:4', 'Job', 25, 4, 'نو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟ څوک چې د مور نه پېدا شوے وى نو هغه کس څنګه صفا کېدے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_4.mp3', '', 1761754199, 1761754199),
(40125, 'Job 25:5', 'Job', 25, 5, 'ګوره، د هغۀ په وړاندې ځلېدونکى سپوږمۍ او ستورى هيڅ هم نۀ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_5.mp3', '', 1761754199, 1761754199),
(40126, 'Job 25:6', 'Job', 25, 6, 'نو بيا انسان څۀ څيز دے يو مېږے کۀ يا يو چينجے؟ د خُدائ پاک په نظر کښې د يو انسان څۀ اهميت دے؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job25_verse_6.mp3', '', 1761754199, 1761754199),
(40127, 'Isaiah 40:1', 'Isaiah', 40, 1, 'ستاسو خدای وایي: «ورکړئ تسلي زما غوره شوي قوم ته ورکړئ تسلي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_1.mp3', '', 1761754199, 1761754199),
(40128, 'Isaiah 40:2', 'Isaiah', 40, 2, 'خبرې وکړئ په نرمه ژبه د اورشلیم خلکو سره او کړئ اعلان هغوی ته چې تېرې شوې مو دي د غلامۍ ورځې او ما بخښلي ګناهونه ستاسو ځکه هغوی ته مې ورکړې سزا د ګناهونو په بدل کې یو په دوه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_2.mp3', '', 1761754199, 1761754199),
(40129, 'Isaiah 40:3', 'Isaiah', 40, 3, 'زه اواز اورم چې یو څوک وهي نارې: «لاره تیاره کړئ په دښته کې څښتن دپاره جوړه صحرا کې کړئ لویه او سیده لاره زمونږ د خدای دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_3.mp3', '', 1761754199, 1761754199),
(40130, 'Isaiah 40:4', 'Isaiah', 40, 4, 'شي به ډکه هره دره شي به هواره هره غونډۍ او غر او شي به هوار کنډ و کپر ځایونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_4.mp3', '', 1761754199, 1761754199),
(40131, 'Isaiah 40:5', 'Isaiah', 40, 5, 'بیا راښکاره به شي جلال د څښتن او ټول انسانان به یې یوځای وویني ځکه داسې ویلي دي خپله څښتن»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_5.mp3', '', 1761754199, 1761754199),
(40132, 'Isaiah 40:6', 'Isaiah', 40, 6, 'یو اواز راځي او وایي: «یو پیغام اعلان کړه» ما پوښتنه وکړه: «کوم پیغام اعلان کړم؟» «دا اعلان وکړه چې د واښو په شان دي ټول انسانان زیات دوام نه کړي د هغوی ژوند له ځنګلي ګلانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_6.mp3', '', 1761754199, 1761754199),
(40133, 'Isaiah 40:7', 'Isaiah', 40, 7, 'څښتن چې کله په هغوی باندې نازل کړي باد واښه وچیږي او ګلان رژیږي هو، په رښتیا چې انسانان دي د واښو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_7.mp3', '', 1761754199, 1761754199),
(40134, 'Isaiah 40:8', 'Isaiah', 40, 8, 'واښه وچیږي او ګلان رژیږي خو تل ترتله به وي ټینګ زمونږ د خدای کلام»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_8.mp3', '', 1761754199, 1761754199),
(40135, 'Isaiah 40:9', 'Isaiah', 40, 9, 'ای صهیونه، وخېژه لوړ غره ته له هغه ځایه ورکړه زېری ای اورشلیمه، په لوړ اواز ورکړه خپل زېری پرته له وېرې ته اعلان کړه هغه د یهودا ښارو ته ووایه: «راروان دی ستاسو خدای»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_9.mp3', '', 1761754199, 1761754199),
(40136, 'Isaiah 40:10', 'Isaiah', 40, 10, 'ګوره، څښتن تعالی راځي او پاچاهي کوي د مټو په زور ګوره، راولي له خپله ځانه سره هغه ژغورل شوي خلک راروان دي هغوی هغه نه مخکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_10.mp3', '', 1761754199, 1761754199),
(40137, 'Isaiah 40:11', 'Isaiah', 40, 11, 'هغه به پام کوي په خپلې رمې لکه د شپون په شان راغونډوي به هغه وري په یوځای او وړي به یې غېږه کې خپل بیایي په مینه به د هغوی مورګانې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_11.mp3', '', 1761754199, 1761754199),
(40138, 'Isaiah 40:12', 'Isaiah', 40, 12, 'ایا کولای شي څوک چې اندازه کړي د بحر اوبه په خپله لپه یا اسمان په خپلې لوېشت باندې؟ ایا کولای شي څوک چې په سطل کې ځای کړي د ټولې ځمکې خاورې یا تله کې وتلي غونډۍ او غرونه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_12.mp3', '', 1761754199, 1761754199),
(40139, 'Isaiah 40:13', 'Isaiah', 40, 13, 'ایا کولای شي څوک چې نصیحت وکړي څښتن ته؟ یا د هغه روح ته لارښوونه وکړي د مشاور په توګه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_13.mp3', '', 1761754199, 1761754199),
(40140, 'Isaiah 40:14', 'Isaiah', 40, 14, 'ایا مجبور ؤ څښتن مشورې ته د چا چې وروښایي هغه ته سمه لاره یا ورزده کړي ورته پوهه او حکمت؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_14.mp3', '', 1761754199, 1761754199),
(40141, 'Isaiah 40:15', 'Isaiah', 40, 15, 'نه، په حقیقت کې ټول قومونه دي څښتن دپاره داسې لکه په سطل کې یو څاڅکی اوبه او یا لکه چې دوړه وي په تله کې هغه د دوړې په شان پورته کوي جزیرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_15.mp3', '', 1761754199, 1761754199),
(40142, 'Isaiah 40:16', 'Isaiah', 40, 16, 'زمونږ څښتن ته د سوځېدونکو نذرانو دپاره کافي نه دي اور بلولو دپاره د لبنان د ځنګلونو هغه ټول حیوانات کافي نه دي د دې ځنګلونو ټولې ونې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_16.mp3', '', 1761754199, 1761754199),
(40143, 'Isaiah 40:17', 'Isaiah', 40, 17, 'هېڅ هم نه دي د څښتن په وړاندې د نړۍ ټول قومونه او په هېڅ کې شمېرل کیږي د هغه په وړاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_17.mp3', '', 1761754199, 1761754199),
(40144, 'Isaiah 40:18', 'Isaiah', 40, 18, 'نو تشبیه کولای شئ خدای د چا سره؟ پرتله کولای شئ هغه د کومې مجسمې سره؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_18.mp3', '', 1761754199, 1761754199),
(40145, 'Isaiah 40:19', 'Isaiah', 40, 19, 'ایا کولای شئ چې پرتله کړئ څښتن له یو بت سره؟ کسبګر هغه قالب کې اچوي اول او ترې جوړوي مجسمه په سرو زرو پوښوي زرګر هغه او جوړوي هم د سپینو زرو زنځیرونه د هغه دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_19.mp3', '', 1761754199, 1761754199),
(40146, 'Isaiah 40:20', 'Isaiah', 40, 20, 'څوک چې غریب وي هغه نه شي ورکولی نذرانه داسې لرګی غوره کوي هغه بت جوړولو لره چې نه ورستیږي هغه بیا ورکوي هغه په لاس د یو ماهر کسبګر چې ترې جوړ کړي یو بت چې راونه غورځیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_20.mp3', '', 1761754199, 1761754199),
(40147, 'Isaiah 40:21', 'Isaiah', 40, 21, 'ایا تاسو په دې نه پوهېږئ؟ ایا تاسو اورېدلي نه وو؟ ایا تاسو ته له پیله ویل شوي نه وو؟ ایا تاسو په دې نه پوهېدئ چې څنګه پیدا شوه دا نړۍ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_21.mp3', '', 1761754199, 1761754199),
(40148, 'Isaiah 40:22', 'Isaiah', 40, 22, 'څښتن ډېر لوړ له ځمکې ناست دی په خپل تخت باندې او د ځمکې اوسېدونکي ورته ښکاري ملخانو په شان خپروي هغه اسمان لکه پردې په شان او ودروي یې لکه خېمې په شان د اوسېدو دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_22.mp3', '', 1761754199, 1761754199),
(40149, 'Isaiah 40:23', 'Isaiah', 40, 23, 'غورځوي له واکه هغه قوي حکمرانان او په نشت بدلوي د نړۍ قوي مشران', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_23.mp3', '', 1761754199, 1761754199),
(40150, 'Isaiah 40:24', 'Isaiah', 40, 24, 'هغوی دي هغو نیالګیو په شان چې کرل شوي اوس تازه او ریښې یې ځغلیدلې نه وي چې راوالوزي کله د څښتن باد هغوی وچ شي او سیلۍ یې یوسي لکه د بوسو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_24.mp3', '', 1761754199, 1761754199),
(40151, 'Isaiah 40:25', 'Isaiah', 40, 25, 'سپېڅلی خدای وایي: «تشبیه کوئ مې تاسو چا سره؟ ایا بل څوک شته زما په شان؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_25.mp3', '', 1761754199, 1761754199),
(40152, 'Isaiah 40:26', 'Isaiah', 40, 26, 'اسمان ته وګورئ! چا پیدا کړي دي دا ستوري چې یې وینئ تاسې؟ دا هغه څوک دی تنظیموي چې اسماني لښکرې ورته معلوم دی شمېر د هغوی، هر یو په نوم پېژني هغه لري دومره توان هغه نه پرېږدي چې ورک شي له هغو نه یو هم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_26.mp3', '', 1761754199, 1761754199),
(40153, 'Isaiah 40:27', 'Isaiah', 40, 27, 'نو ای یعقوبه، ولې وایئ او ای اسراییلو، بیا کوئ شکایت ولې چې خبر نه دی څښتن زمونږ له کړاوونو څخه او نه کوي پام زمونږ حق ته زمونږ خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_27.mp3', '', 1761754199, 1761754199),
(40154, 'Isaiah 40:28', 'Isaiah', 40, 28, 'ایا نه پوهېږئ او تاسو نه دي اورېدلي چې څښتن دی تلپاتې خدای او پیدا کړې ده هغه ټوله نړۍ؟ هغه هېڅکله نه ستړی کیږي او ستومانه کیږي نه او نه پوهیږي هېڅوک د هغه فکرونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_28.mp3', '', 1761754199, 1761754199),
(40155, 'Isaiah 40:29', 'Isaiah', 40, 29, 'هغه ستړو ته قوت وربخښي او زیاتوي زور د کمزورو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_29.mp3', '', 1761754199, 1761754199),
(40156, 'Isaiah 40:30', 'Isaiah', 40, 30, 'حتی ځوانان هم شي ستړي او ستومانه او زلمي هم له ستړیا رالویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_30.mp3', '', 1761754199, 1761754199),
(40157, 'Isaiah 40:31', 'Isaiah', 40, 31, 'خو چې څښتن ته منتظر دي هغوی وبه مومي هغوی نوی زور په وزرونو باندې به الوزي لکه عقاب په شان هغوی به منډې وهي، خو ستومانه کیږي به نه هغوی به ګرځي، خو ستړي کیږي به نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah40_verse_31.mp3', '', 1761754199, 1761754199),
(40158, 'Exodus 8:1', 'Exodus', 8, 1, 'بیا څښتن موسی ته وویل: «فرعون ته ورشه او هغه ته ووایه چې څښتن وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_1.mp3', '', 1761754199, 1761754199),
(40159, 'Exodus 8:2', 'Exodus', 8, 2, 'که چېرې ته د هغوی د پرېښودلو څخه انکار وکړې، زه به ستا په ټول هېواد باندې د چونګښو بلا نازله کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_2.mp3', '', 1761754199, 1761754199),
(40160, 'Exodus 8:3', 'Exodus', 8, 3, 'د نیل سیند به د چونګښو څخه ډک شي. هغوی به ستا ماڼۍ او ستا د خوب کوټې ته درننوځي او ستا کټ ته به دروخېژي. حتی ستا د قوم او د درباریانو کورونو او ستا تنورونو او د خمیره کولو لګنونو ته به هم ورننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_3.mp3', '', 1761754199, 1761754199),
(40161, 'Exodus 8:4', 'Exodus', 8, 4, 'چونګښې به ستا، ستا د قوم او ستا د ټولو درباریانو سرونو باندې ټوپونه وهي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_4.mp3', '', 1761754199, 1761754199),
(40162, 'Exodus 8:5', 'Exodus', 8, 5, 'څښتن موسی ته وویل: «هارون ته ووایه: خپله امسا د ویالو، نهرونو او ډنډونو خواته ونیسه، ترڅو چونګښې دباندې ووځي او د مصر ځمکه په هغو پټه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_5.mp3', '', 1761754199, 1761754199),
(40163, 'Exodus 8:6', 'Exodus', 8, 6, 'نو هارون خپله امسا د اوبو په سر ونیوله او چونګښې راووتلې او ځمکه ورباندې پټه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_6.mp3', '', 1761754199, 1761754199),
(40164, 'Exodus 8:7', 'Exodus', 8, 7, 'خو جادوګرانو هم همداسې کار وکړ. هغوی هم د جادو په وسیله چونګښې ځمکې ته راوویستلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_7.mp3', '', 1761754199, 1761754199),
(40165, 'Exodus 8:8', 'Exodus', 8, 8, 'فرعون موسی او هارون راوغوښتل او ورته ویې ویل: «تاسو څښتن ته دعا وکړئ چې زمونږ څخه دا چونګښې لېرې کړي، نو زه به ستاسو قوم پرېږدم چې لاړ شي او څښتن ته قربانۍ وړاندې کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_8.mp3', '', 1761754199, 1761754199),
(40166, 'Exodus 8:9', 'Exodus', 8, 9, 'موسی په ځواب کې وویل: «زه به ستا دپاره دعا وکړم. ماته وخت وټاکه چې زه کله ستا، ستا د درباریانو او ستا د قوم دپاره دعا وکړم. بیا به تاسو او ستاسو کورونه د چونګښو څخه خلاص شي او یوازې د نیل په سیند کې به چونګښې پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_9.mp3', '', 1761754199, 1761754199),
(40167, 'Exodus 8:10', 'Exodus', 8, 10, 'فرعون په ځواب کې وویل: «سبا زما دپاره دعا وکړه.» موسی وویل: «څنګه چې ستا خوښه وي زه به هماغسې وکړم. بیا به ته پوه شې چې زمونږ د څښتن خدای په شان بل خدای نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_10.mp3', '', 1761754199, 1761754199),
(40168, 'Exodus 8:11', 'Exodus', 8, 11, 'ته، ستا درباریان او ستا خلک به له چونګښو څخه خلاص شئ او چونګښې به د نیل د سیند څخه پرته په بل ځای کې پاتې نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_11.mp3', '', 1761754199, 1761754199),
(40169, 'Exodus 8:12', 'Exodus', 8, 12, 'بیا موسی او هارون د فرعون څخه لاړل او موسی څښتن ته سوال وکړ چې هغه چونګښې له منځه یوسي چې څښتن په فرعون باندې نازلې کړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_12.mp3', '', 1761754199, 1761754199),
(40170, 'Exodus 8:13', 'Exodus', 8, 13, 'څښتن د موسی سوال قبول کړ او هغه چونګښې چې په کورونو، حوېلیو او پټیو کې وې، مړې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_13.mp3', '', 1761754199, 1761754199),
(40171, 'Exodus 8:14', 'Exodus', 8, 14, 'مصریانو هغه ډېرۍ کړې او ټوله ځمکه بد بوی ونیوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_14.mp3', '', 1761754199, 1761754199),
(40172, 'Exodus 8:15', 'Exodus', 8, 15, 'کله چې فرعون ولیدل چې چونګښې مړې شوې، هغه بیا خپل زړه سخت کړ او لکه څنګه چې څښتن ویلي وو، هغه د موسی او هارون خبرو ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_15.mp3', '', 1761754199, 1761754199),
(40173, 'Exodus 8:16', 'Exodus', 8, 16, 'بیا څښتن موسی ته وویل: «هارون ته ووایه چې په خپله امسا باندې ځمکه ووهي چې د مصر ټولې خاورې په میاشو بدلې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_16.mp3', '', 1761754199, 1761754199),
(40174, 'Exodus 8:17', 'Exodus', 8, 17, 'نو هارون ځمکه په امسا باندې ووهله او د مصر ټولې خاورې په میاشو بدلې شوې او ټول انسانان او حیوانات په کې پټ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_17.mp3', '', 1761754199, 1761754199),
(40175, 'Exodus 8:18', 'Exodus', 8, 18, 'جادوګرانو هڅه وکړه چې د جادو په وسیله میاشي پیدا کړي، خو هغوی ونه شو کولای. انسانانو او حیواناتو پورې میاشي نښتي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_18.mp3', '', 1761754199, 1761754199),
(40176, 'Exodus 8:19', 'Exodus', 8, 19, 'جادوګرانو فرعون ته وویل: «دا کار خدای کړی دی!» خو د فرعون زړه سخت ؤ او څنګه چې څښتن ویلي وو، فرعون د موسی او هارون خبرو ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_19.mp3', '', 1761754199, 1761754199),
(40177, 'Exodus 8:20', 'Exodus', 8, 20, 'څښتن موسی ته وویل: «سبا سهار وختي پاڅه او کله چې فرعون سیند ته ځي، ورشه او ورسره وګوره او هغه ته ووایه چې څښتن داسې وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_20.mp3', '', 1761754199, 1761754199),
(40178, 'Exodus 8:21', 'Exodus', 8, 21, 'که ته زما قوم پرېنږدې چې لاړ شي، زه به په تا، ستا په درباریانو او ستا په قوم او په کورونو باندې مچان نازل کړم. د مصریانو کورونه به د مچانو څخه ډک شي او ځمکه به ورباندې پټه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_21.mp3', '', 1761754199, 1761754199),
(40179, 'Exodus 8:22', 'Exodus', 8, 22, 'خو زه به د جوشن سیمه چې زما قوم په کې اوسيږي، وژغورم چې هلته هېڅ مچان نه وي. دا کار د دې دپاره کوم، ترڅو تاسو پوه شئ چې زه حتی په دې خاوره باندې هم اختیار لرم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_22.mp3', '', 1761754199, 1761754199),
(40180, 'Exodus 8:23', 'Exodus', 8, 23, 'زه به ستا او د خپل قوم ترمنځ ښکاره فرق وکړم. دا معجزه به سبا پېښیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_23.mp3', '', 1761754199, 1761754199),
(40181, 'Exodus 8:24', 'Exodus', 8, 24, 'نو څښتن د فرعون په ماڼۍ او د هغه د درباریانو په کورونو باندې ډېر زیات مچان نازل کړل. مچانو د مصر ټول هېواد وران کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_24.mp3', '', 1761754199, 1761754199),
(40182, 'Exodus 8:25', 'Exodus', 8, 25, 'بیا فرعون موسی او هارون راوغوښتل او هغوی ته یې وویل: «لاړ شئ او په همدې هېواد کې خپل خدای ته قربانۍ وړاندې کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_25.mp3', '', 1761754199, 1761754199),
(40183, 'Exodus 8:26', 'Exodus', 8, 26, 'موسی په ځواب کې وویل: «دا ښه کار نه دی. ځکه مصریان به زمونږ څخه خفه شي چې مونږ خپل څښتن خدای ته حیوانات قرباني کړو. که چېرې دا حیوانات په داسې ځای کې قرباني کړو چې مصریان مو وویني، نو هغوی به مونږ سنګسار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_26.mp3', '', 1761754199, 1761754199),
(40184, 'Exodus 8:27', 'Exodus', 8, 27, 'لکه څنګه چې زمونږ څښتن خدای حکم کړی دی، مونږ باید هغه ته د قربانۍ وړاندې کولو په خاطر درې ورځې په دښته کې سفر وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_27.mp3', '', 1761754199, 1761754199),
(40185, 'Exodus 8:28', 'Exodus', 8, 28, 'فرعون وویل: «زه به تاسو پرېږدم چې لاړ شئ او خپل څښتن خدای ته په دښته کې قربانۍ وړاندې کړئ. خو ډېر لېرې لاړ نه شئ او زما دپاره دعا وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_28.mp3', '', 1761754199, 1761754199),
(40186, 'Exodus 8:29', 'Exodus', 8, 29, 'موسی په ځواب کې وویل: «څنګه چې زه لاړ شم، نو ستا دپاره به دعا وکړم چې څښتن ستا، ستا له درباریانو او ستا له قوم څخه مچان لېرې کړي. خو ته به بیا مونږ نه غولوې او د قوم مخنیوی به نه کوې چې هغوی څښتن ته قرباني وړاندې کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_29.mp3', '', 1761754199, 1761754199),
(40187, 'Exodus 8:30', 'Exodus', 8, 30, 'موسی د فرعون څخه لاړ او څښتن ته یې دعا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_30.mp3', '', 1761754199, 1761754199),
(40188, 'Exodus 8:31', 'Exodus', 8, 31, 'څښتن د موسی دعا قبوله کړه. مچانو فرعون، د هغه درباریان او د هغه قوم پرېښودل. یو مچ هم پاتې نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_31.mp3', '', 1761754199, 1761754199),
(40189, 'Exodus 8:32', 'Exodus', 8, 32, 'خو دا ځل هم فرعون خپل زړه سخت کړ او د اسراییلو قوم یې پرېنښود چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus8_verse_32.mp3', '', 1761754199, 1761754199),
(40190, 'Esther 6:1', 'Esther', 6, 1, 'په هغه شپه پاچا ته هېڅ خوب نه ورته، نو هغه امر وکړ چې د امپراتورۍ د پېښو تاریخي کتاب راوړئ او ماته یې په لوړ اواز ولولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_1.mp3', '', 1761754199, 1761754199),
(40191, 'Esther 6:2', 'Esther', 6, 2, 'په هغه کې یې داسې لیکنه وموندله چې څنګه مردخای د پاچا د وژلو هغه دسیسه چې د پاچا د کوټې د دروازې د دوو خصي شویو ساتونکو یعنې بګتان او تارش له خوا ترتیب شوې وه، ښکاره او بربنډه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_2.mp3', '', 1761754199, 1761754199),
(40192, 'Esther 6:3', 'Esther', 6, 3, 'پاچا پوښتنه وکړه: «د دې کار په خاطر مونږ مردخای ته څومره عزت او انعام ورکړی دی؟» د هغه خدمتګارانو په ځواب کې وویل: «د هغه دپاره هېڅ نه دي شوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_3.mp3', '', 1761754199, 1761754199),
(40193, 'Esther 6:4', 'Esther', 6, 4, 'پاچا پوښتنه وکړه: «ایا زما د درباریانو څخه څوک په ماڼۍ کې شته؟» نو هامان په دې وخت کې د ماڼۍ باندینۍ حوېلۍ ته راغی. هغه د پاچا څخه غوښتل مردخای په هغه دار باندې چې د هغه دپاره یې تیار کړی ؤ، ځوړند کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_4.mp3', '', 1761754199, 1761754199),
(40194, 'Esther 6:5', 'Esther', 6, 5, 'د هغه خدمتګارانو په ځواب کې وویل: «هامان دلته په دربار کې دی.» پاچا وویل: «هغه دننه راولئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_5.mp3', '', 1761754199, 1761754199),
(40195, 'Esther 6:6', 'Esther', 6, 6, 'کله چې هامان دننه راغی، نو پاچا ورڅخه پوښتنه وکړه: «د هغه سړي سره چې پاچا غواړي عزت ورته ورکړي، باید څه وکړو؟» نو بیا هامان د خپل ځان سره فکر وکړ: «داسې څوک شته چې پاچا غواړي هغه ته زما نه زیات عزت ورکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_6.mp3', '', 1761754199, 1761754199),
(40196, 'Esther 6:9', 'Esther', 6, 9, 'بیا یو لوړ رتبه مامور ته دنده وسپارئ چې هغه شاهي چپنه هغه ته ورواغوندي، په اس باندې یې سپور کړي، د ښار په چوک کې دې وګرځوي او په لوړ اواز دې ووایي: ‹ګورئ، د هغه سړي سره چې پاچا غواړي هغه ته عزت ورکړي داسې عمل کیږي!›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_9.mp3', '', 1761754199, 1761754199),
(40197, 'Esther 6:10', 'Esther', 6, 10, 'بیا پاچا هامان ته وویل: «سمدلاسه لاړ شه، چپنه او اس د مردخای یهودي دپاره چې د ماڼۍ په دروازې کې ناست دی، تیار کړه. لکه څنګه چې تا وړاندیز وکړ هماغسې وکړه، پام کوه چې کوم شی دې هېر نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_10.mp3', '', 1761754199, 1761754199),
(40198, 'Esther 6:11', 'Esther', 6, 11, 'نو بیا هامان چپنه او اس تیار کړل. مردخای ته یې چپنه واغوستله، هغه یې په اس باندې سپور کړ، د ښار په چوک کې یې وګرځاوه او د هغه په مخکې یې چیغې وهلې: «ګورئ، د هغه سړي سره چې پاچا غواړي هغه ته عزت ورکړي داسې عمل کیږي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_11.mp3', '', 1761754199, 1761754199),
(40199, 'Esther 6:12', 'Esther', 6, 12, 'له هغې وروسته مردخای بېرته د ماڼۍ دروازې ته راستون شو. خو هامان په داسې حال کې چې ډېر غمجن ؤ او د شرم نه یې خپل مخ پټ کړی ؤ، په بیړه خپل کور ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_12.mp3', '', 1761754199, 1761754199),
(40200, 'Esther 6:13', 'Esther', 6, 13, 'هرڅه چې ورباندې پېښ شوي وو هغه یې خپلې ښځې زرش او خپلو ملګرو ته بیان کړل. د هغه ښځې زرش او د هغه ماهرو مشاورانو هغه ته وویل: «ته د مردخای په وړاندې کمزوری کېږې. هغه یهودي دی، په هغه باندې بریالی کېدای نه شې. هغه به په رښتیا تاته ماتې درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_13.mp3', '', 1761754199, 1761754199),
(40201, 'Esther 6:14', 'Esther', 6, 14, 'په داسې حال کې چې هغوی لا خبرې کولې د ماڼۍ خصیان راورسېدل چې هامان په بیړه هغې مېلمستیا ته بوځي چې استر تیاره کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther6_verse_14.mp3', '', 1761754199, 1761754199),
(40202, 'Job 12:1', 'Job', 12, 1, 'نو ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_1.mp3', '', 1761754199, 1761754199),
(40203, 'Job 12:2', 'Job', 12, 2, '”په دې کښې هيڅ شک نشته چې تاسو په هر څۀ پوهېږئ، او چې کله تاسو مرئ نو ستاسو پوهه به تاسو سره ختمه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_2.mp3', '', 1761754199, 1761754199),
(40204, 'Job 12:3', 'Job', 12, 3, 'خو زۀ هم ستاسو په شان پوهه لرم، زۀ ستاسو نه کم نۀ يم، چې تاسو څۀ وايئ نو په دې باندې هر څوک پوهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_3.mp3', '', 1761754199, 1761754199),
(40205, 'Job 12:4', 'Job', 12, 4, 'زۀ د خپلو دوستانو دپاره يوه مسخره يم، زۀ چې خُدائ پاک ته آواز کوم نو هغه زما آواز اورى، زۀ يو داسې سړے يم چې صادق او بې‌داغه يم، خو زۀ مسخره جوړ شوے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_4.mp3', '', 1761754199, 1761754199),
(40206, 'Job 12:5', 'Job', 12, 5, 'کوم خلق چې په آرام وى نو هغوئ په هغه چا پورې خندا کوى چې څوک په تکليف کښې دى، او هغه خلقو له ديکه ورکوى د چا چې پښې ښوئيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_5.mp3', '', 1761754199, 1761754199),
(40207, 'Job 12:6', 'Job', 12, 6, 'د ډاکوانو کورونه په امن کښې وى، او چې څوک خُدائ پاک راپاروى نو هغه محفوظ وى، اګر چې هغوئ د خُدائ پاک په ځائ په خپل طاقت باندې بهروسه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_6.mp3', '', 1761754199, 1761754199),
(40208, 'Job 12:7', 'Job', 12, 7, 'خو د ځناورو نه تپوس وکړئ او هغوئ به ستاسو رهنمائى وکړى، او په هوا کښې د مارغانو نه تپوس وکړئ، نو هغوئ به تاسو ته ښودنه وکړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_7.mp3', '', 1761754199, 1761754199),
(40209, 'Job 12:8', 'Job', 12, 8, 'او د زمکې د بوټو نه تپوس وکړئ، نو دا به تاسو ته ښودنه وکړى، او د سمندر کبانو نه تپوس وکړئ نو هغه به تاسو ته دا بيان وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_8.mp3', '', 1761754199, 1761754199),
(40210, 'Job 12:9', 'Job', 12, 9, 'ځکه چې هغوئ ټولو ته پته ده چې زما تکليف د مالِک خُدائ د طرف نه دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job12_verse_9.mp3', '', 1761754199, 1761754199);